import{_ as n,o as e,c as a,a5 as t}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"FR 3.5.2 — Guest xem gói quảng bá và Client xem gói workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-2-view-the-template-media-package/spec.md","filePath":"feature/media-package-campaign/3-5-2-view-the-template-media-package/spec.md"}'),h={name:"feature/media-package-campaign/3-5-2-view-the-template-media-package/spec.md"};function c(g,i,u,l,r,m){return e(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="fr-3-5-2-—-guest-xem-goi-quang-ba-va-client-xem-goi-workspace" tabindex="-1">FR 3.5.2 — Guest xem gói quảng bá và Client xem gói workspace <a class="header-anchor" href="#fr-3-5-2-—-guest-xem-goi-quang-ba-va-client-xem-goi-workspace" aria-label="Permalink to &quot;FR 3.5.2 — Guest xem gói quảng bá và Client xem gói workspace&quot;">​</a></h1><p>Cập nhật BA 2026-11-05, chờ triển khai. Theo <a href="./../guest-sharing-manager-led/spec.html">spec hành trình mới</a>.</p><h2 id="muc-tieu" tabindex="-1">Mục tiêu <a class="header-anchor" href="#muc-tieu" aria-label="Permalink to &quot;Mục tiêu&quot;">​</a></h2><p>Khách xem gói Agency qua link được chia sẻ trước khi có tài khoản/workspace. Client đã được mời xem gói thực hiện đã thống nhất trong workspace.</p><p>Cập nhật 2026-11-06: Manager phụ trách/Owner có quyền quản lý cũng chia sẻ được Custom Package workspace qua link guest và xuất ảnh/PDF để trao đổi với Client bên ngoài. Cơ chế bảo mật nâng cao để team bàn sau, chưa yêu cầu OTP/mật khẩu/xác minh email.</p><h2 id="tieu-chi-nghiem-thu" tabindex="-1">Tiêu chí nghiệm thu <a class="header-anchor" href="#tieu-chi-nghiem-thu" aria-label="Permalink to &quot;Tiêu chí nghiệm thu&quot;">​</a></h2><ul><li>Guest mở link gói quảng bá mà không cần đăng nhập, lời mời hoặc membership.</li><li>Nội dung gồm Agency, tên gói, phạm vi, dịch vụ/hạng mục, sản lượng, đơn vị, mô tả, tiêu chí và ngân sách/thời lượng nếu được cung cấp.</li><li>Link luôn đọc bản mới nhất đã lưu của đúng gói Agency hoặc workspace được chia sẻ. Link workspace không lấy lại nội dung mẫu Agency. Tải lại sau khi người quản lý sửa phải thấy bản mới.</li><li>Ảnh/PDF đã xuất thể hiện bản tại thời điểm xuất và có thông tin ngày xuất. Xuất đủ nội dung, hiển thị đúng tiếng Việt và hạng mục dài.</li><li>Guest chỉ xem nội dung gói được chia sẻ, gồm điều khoản của chính gói đó. Link không cấp quyền xem workspace, Client Profile, Campaign/task, comment, approval hoặc dữ liệu nội bộ khác.</li><li>Client đã tham gia đúng workspace xem gói thực hiện và nội dung liên quan theo quyền hiện hành.</li><li>Client không có bước chọn, request-change hoặc approve Package trong hành trình mới.</li><li>Trạng thái chưa có gói hướng dẫn Manager thiết lập và cho Client biết đang chuẩn bị. Không yêu cầu Client duyệt để tiếp tục.</li><li>Link sai/không còn khả dụng, mất kết nối, tải và xuất file lỗi có trạng thái phù hợp. Dữ liệu lỗi không được thay bằng gói giả.</li><li>Hỗ trợ vi/en, light/dark, bàn phím và mobile theo theme hiện hành.</li></ul><h2 id="hop-đong-du-lieu" tabindex="-1">Hợp đồng dữ liệu <a class="header-anchor" href="#hop-đong-du-lieu" aria-label="Permalink to &quot;Hợp đồng dữ liệu&quot;">​</a></h2><p>Phải tách dữ liệu public khỏi dữ liệu workspace ở phía server. Guest không dùng endpoint nội bộ có quyền rộng chỉ vì cùng hiển thị một gói. Tên route, cấu hình chia sẻ và cơ chế export chốt trong plan.</p>',9)])])}const s=n(h,[["render",c]]);export{p as __pageData,s as default};
